<?php $successful=$order['estado']!=='cancelado';$unitCount=array_sum(array_map(static fn($line)=>(int)$line['cantidad'],$lines));?>
<section class="content order-page <?=$successful?'is-success':'is-cancelled'?>">
 <header class="order-heading"><div class="order-title-wrap"><span class="order-brand-mark" aria-hidden="true">K</span><div><p class="order-eyebrow">KROMA · DETALLE DE COMPRA</p><h1><?=$successful?'Pedido realizado correctamente':'No se pudo confirmar el pedido'?></h1><p class="order-number">Pedido <strong><?=h($order['numero_pedido'])?></strong></p></div></div><span class="order-status"><?=kroma_icon($successful?'check':'info')?><?=h(order_status_label($order['estado']))?></span></header>
 <?php if(!$successful):?><div class="order-cancelled-note"><?=kroma_icon('info')?>El pago de demostración fue rechazado. No se descontó stock. Podés volver al catálogo e intentarlo nuevamente.</div><?php endif?>
 <section class="order-overview" aria-label="Resumen del pedido"><div class="order-overview-item"><span class="order-overview-icon"><?=kroma_icon('calendar')?></span><span><small>Estado</small><strong><?=h(order_status_label($order['estado']))?></strong></span></div><div class="order-overview-item"><span class="order-overview-icon"><?=kroma_icon('money')?></span><span><small>Total</small><strong><?=ars($order['total'])?></strong></span></div><div class="order-overview-item"><span class="order-overview-icon"><?=kroma_icon($order['modalidad_entrega']==='retiro'?'refresh':'truck')?></span><span><small>Entrega</small><strong><?=h(delivery_mode_label($order['modalidad_entrega']))?></strong></span></div></section>
 <section class="order-products-card"><div class="order-products-heading"><span><?=kroma_icon('package')?></span><div><p class="order-eyebrow">RESUMEN</p><h2>Productos del pedido</h2></div><small><?=$unitCount?> <?=($unitCount===1?'producto':'productos')?></small></div><div class="order-table-wrap"><table class="order-table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th></tr></thead><tbody><?php foreach($lines as $line):?><tr><td><div class="order-product"><span class="order-product-image"><img data-auto-product-image data-product-id="<?=(int)$line['id_producto']?>" data-image-query="<?=h(trim(($line['marca']??'').' '.$line['nombre_producto_historico'].' '.($line['modelo_historico']??'')))?>" src="<?=h(product_image_fallback($line))?>" data-local-image-fallback="<?=h(product_image_local_fallback($line))?>" alt="<?=h($line['nombre_producto_historico'])?>" loading="lazy"></span><span><strong><?=h($line['nombre_producto_historico'])?></strong><?php if(!empty($line['modelo_historico'])):?><small><?=h($line['modelo_historico'])?></small><?php endif?></span></div></td><td><span class="order-quantity"><?=(int)$line['cantidad']?></span></td><td class="order-price"><?=ars($line['subtotal_linea'])?></td></tr><?php endforeach?></tbody></table></div><div class="order-products-footer"><span>Total del pedido</span><strong><?=ars($order['total'])?></strong></div></section>
 <?php if($order['modalidad_entrega']==='envio'&&!empty($order['direccion_entrega_historica'])):?><section class="order-delivery-note"><span><?=kroma_icon('truck')?></span><div><strong>Dirección de entrega</strong><p><?=nl2br(h($order['direccion_entrega_historica']))?></p></div></section><?php endif?>
 <nav class="order-actions" aria-label="Acciones del pedido"><a class="btn" href="?action=orders">Ver mis pedidos</a><a class="lightbtn" href="?action=catalog">Seguir comprando</a></nav>
